/* Compact acquisition UX for each realm's three-spell pool. The prototype simulates trusted idle reports; production decisions belong to the server. */
/* Placeholder art for the eight proposed pool spells: compositions of existing atlas/HUD sprites, marked data-art="placeholder" until reviewed pixel art replaces them. */
const RealmSpellArt=(()=>{
    const parts={ashfall:()=>[0,1,2].map(i=>`<span class="fall-${i}">${sprite('fire')}</span>`).join(''),flarejavelin:()=>sprite('fire'),rimenova:()=>[0,90,180,270].map(a=>`<span style="--petal:${a}deg">${ui('ice')}</span>`).join(''),frostfang:()=>sprite('ice'),quartzspike:()=>sprite('shards'),bramblesnare:()=>ui('earth'),squallblade:()=>ui('wind'),thundergust:()=>ui('wind')};
    const placeholders=Object.keys(parts);
    const markup=(name,extra='')=>`<span class="sprite realm-spell-art placeholder-art ${name} ${extra}" data-sprite="${name}" data-art="placeholder" aria-hidden="true">${parts[name]()}</span>`;
    return {placeholders,markup};
})();
const RealmDiscoveries=(()=>{
    const M=MageIdleSpells;let serial=0;
    const windowId=()=> 'idle-window-'+(++serial),status=r=>M.status(state,r),names=list=>list.map(d=>d.name);
    const unseen=r=>M.pool(r).some(d=>state.realmFinds.unseen.includes(d.name));
    // One sample per possible roll plus one pick sample per possible find; unused samples are ignored by the model.
    const samples=(p,r,seconds)=>{const rolls=M.remaining(p,r).length?Math.floor((p.realmFinds.bank[r]+seconds)/M.interval):0;return Array.from({length:rolls*2},()=>Math.random());};
    const clock=s=>Math.floor(s/60)+':'+String(s%60).padStart(2,'0');
    const span=s=>{const h=Math.floor(s/3600),m=Math.ceil(s%3600/60);return h&&m===60?(h+1)+'h':h?h+'h '+String(m).padStart(2,'0')+'m':m+'m';};
    const guarantee=s=>`Guaranteed within ${s.guaranteeRolls} ${s.guaranteeRolls===1?'roll':'rolls'} · ≤${span(s.guaranteeSeconds)} idle`;
    function trigger(r=state.realm,small=false){const s=status(r),found=s.owned.length+s.pending.length,fresh=unseen(r)||s.pending.length;return `<button class="realm-find-trigger ${small?'small':''} ${fresh?'new-find':''}" data-discovery-realm="${r}" aria-label="${realms[r]} realm-exclusive spells, ${found} of ${s.pool.length} found. ${s.complete&&!s.pending.length?'Pool complete':s.pending.length?s.pending.length+' waiting on the ground':Math.round(s.chance*100)+' percent next drop chance, '+s.misses+' rolls without a find'}">${s.pending.length?sprite(s.pending[0].art):s.complete?sprite(s.pool[0].art):ui('book')}<small>${s.complete&&!s.pending.length?'✓':s.pending.length?'Loot':found+'/'+s.pool.length}</small>${fresh?'<b class="find-new">!</b>':''}</button>`;}
    function tile(d,s){const has=s.owned.includes(d),waits=s.pending.includes(d),inner=`${sprite(d.art)}<strong>${d.name}</strong><small>${has?glyph('check')+' Owned':waits?'Loot':'Not found'}</small>`;return has?`<button class="realm-pool-tile owned" data-realm-spell="${d.id}" aria-label="${d.name}, in collection. View spell">${inner}</button>`:waits?`<button class="realm-pool-tile waiting" data-ground-items aria-label="${d.name}, waiting on the ground. View waiting items">${inner}</button>`:`<div class="realm-pool-tile unknown" role="img" aria-label="${d.name}, not found yet">${inner}</div>`;}
    function odds(r,s){return `<div class="find-odds"><div><small>Next drop chance</small><strong data-find-chance>${Math.round(s.chance*100)}%</strong></div><div><small>Idle until next roll</small><strong data-find-next>${clock(s.nextSeconds)}</strong></div></div><div class="find-pity"><span>Rolls without a find <b data-find-misses>${s.misses} / ${M.hardLimit}</b></span><div class="find-pips" role="img" aria-label="${s.misses} misses, guaranteed by roll ${M.hardLimit}">${Array.from({length:M.hardLimit},(_,i)=>`<i class="${i<s.misses?'filled':''}"></i>`).join('')}</div><strong data-find-guarantee>${guarantee(s)}</strong></div>`;}
    function detail(){const r=state.modal.realm,s=status(r),found=s.owned.length+s.pending.length;return `<div class="realm-find-head"><span class="kicker">${realms[r]} IDLE · REALM POOL</span><strong data-pool-count>${found} / ${s.pool.length} found</strong></div><div class="realm-pool" role="group" aria-label="${realms[r]} realm spell pool">${s.pool.map(d=>tile(d,s)).join('')}</div>${s.complete?`<div class="find-owned">${glyph('check')} ${s.pending.length?'Pool found · pick up waiting spells':'Pool complete · no more rolls here'}</div>`:odds(r,s)}${s.complete&&s.pending.length?`<button class="realm-source-link" data-ground-items>${ui('book')} ${s.pending.length} waiting on the ground</button>`:''}${s.complete?'':`<p class="find-source">${ui(realms[r].toLowerCase(),'inline-icon')} Idle in ${realms[r]} realm · Any farming place</p><div class="stack">${btn(canVisit(r)?'Farm '+realms[r]+' realm':'Realm locked','farmRealmFind',false,!canVisit(r))}</div>`}<details class="find-rules"><summary>Drop rules</summary><p>One roll per ${M.interval/60} minutes of credited idle. Chance starts at 10%, rises after ${M.hardLimit-4} misses and reaches 100% on roll ${M.hardLimit} (about ${M.interval*M.hardLimit/3600}h).</p><p>A find is a random spell from this realm you do not own yet; no duplicates before the pool is complete. Pity is shared by the realm and kept when you travel. Time away counts up to 12h. Extra manual kills do not add rolls.</p></details>`;}
    function open(r){state.realmFinds.unseen=state.realmFinds.unseen.filter(n=>!names(M.pool(r)).includes(n));openModal({type:'realmDiscovery',realm:r});}
    function tick(){if(!state.idle.some(Boolean))return;const r=state.realm,out=M.credit(state,{id:state.realmFindWindow+'-'+state.seconds,windowId:state.realmFindWindow,realm:r,seconds:1,samples:samples(state,r,1)});if(!out.ok)return;if(out.receipt.found.length)notify('Item dropped · '+out.receipt.found[0]);refresh();}
    function refresh(){for(const el of phone.querySelectorAll('[data-discovery-realm]')){const r=Number(el.dataset.discoveryRealm),temp=document.createElement('div');temp.innerHTML=trigger(r,el.classList.contains('small'));const next=temp.firstElementChild;el.className=next.className;el.innerHTML=next.innerHTML;el.setAttribute('aria-label',next.getAttribute('aria-label'));}
        if(state.modal?.type!=='realmDiscovery')return;const r=state.modal.realm,s=status(r),count=phone.querySelector('[data-pool-count]');
        if(count&&count.textContent!==(s.owned.length+s.pending.length)+' / '+s.pool.length+' found')return render(true);
        const set=(sel,text)=>{const el=phone.querySelector(sel);if(el)el.textContent=text;};set('[data-find-next]',clock(s.nextSeconds));set('[data-find-chance]',Math.round(s.chance*100)+'%');set('[data-find-misses]',s.misses+' / '+M.hardLimit);set('[data-find-guarantee]',guarantee(s));
        phone.querySelectorAll('.find-pips i').forEach((el,i)=>el.classList.toggle('filled',i<s.misses));phone.querySelector('.find-pips')?.setAttribute('aria-label',s.misses+' misses, guaranteed by roll '+M.hardLimit);}
    function prepareReturn(){const r=state.returned.realm??state.realm,seconds=Math.min(12,state.returned.hours)*3600,params={id:'return-'+(++serial),windowId:'absence-'+serial,realm:r,seconds,source:'absence',samples:samples(state,r,seconds)},copy=structuredClone(state),out=M.credit(copy,params);state.returned.realmFind={params,receipt:out.receipt};}
    function returnMarkup(){const report=state.returned?.realmFind;if(!report?.receipt?.found.length)return '';const found=report.receipt.found.map(n=>M.definitions.find(d=>d.name===n));return `<div class="return-find">${found.map(d=>sprite(d.art)).join('')}<div><small>${state.returnClaimed?'Waiting on the ground':'Pick up in realm'}</small><strong title="${found.map(d=>d.name).join(', ')}">${found.length>1?found.length+' '+realms[report.receipt.realm]+' spells':found[0].name}</strong></div>${state.returnClaimed?glyph('check'):ui('book','inline-icon')}</div>`;}
    function claimReturn(){const report=state.returned?.realmFind;const ok=!report||M.credit(state,report.params).ok;if(ok)GroundLoot.syncDiscoveries();return ok;}
    function farm(){const r=state.modal.realm;if(RealmProgression.visit(r))go('realm');}
    // Owned pool spells open their collection card for explicit equip or try; waiting spells use the ground list.
    function handle(el){if(!el.dataset.realmSpell)return false;const d=M.definitions.find(d=>d.id===el.dataset.realmSpell);if(d&&state.unlocked.includes(d.name)){state.collectionTab='spells';openModal({type:'card',kind:'spells',id:spells.findIndex(s=>s.name===d.name)});}return true;}
    return {windowId,trigger,detail,open,tick,refresh,prepareReturn,returnMarkup,claimReturn,farm,handle};
})();
